import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from "../api";

const ROLES = [
  {id:"student", label:"Student", desc:"Find internships"},
  {id:"company", label:"Company", desc:"Post offers"},
];

export default function Register() {
  const [step, setStep] = useState(1);
  const [role, setRole] = useState(null);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({ fullname: "", email: "", password: "" });
  

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await api.post('register/', {
        username: form.email,
        email: form.email,
        fullname: form.fullname,
        password: form.password,
        role: role
      });
      setStep(3);
    } catch (error) {
      alert("Registration failed. Email might already be in use.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#fdf9f5] flex items-center justify-center p-6">
      <div className="w-full max-w-md bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
        
        {step === 1 && (
          <div>
            <h2 className="text-2xl font-bold mb-6">Join as a...</h2>
            <div className="grid grid-cols-2 gap-4 mb-8">
              {ROLES.map(r => (
                <div key={r.id} onClick={() => setRole(r.id)}
                  className={`p-4 border-2 rounded-2xl cursor-pointer text-center transition-all ${role===r.id ? "border-blue-600 bg-blue-50" : "border-slate-100"}`}>
                  <div className="font-bold">{r.label}</div>
                  <div className="text-xs text-slate-400">{r.desc}</div>
                </div>
              ))}
            </div>
            <button disabled={!role} onClick={() => setStep(2)} className="w-full bg-slate-900 text-white py-3 rounded-xl font-bold disabled:bg-slate-200">Next</button>
          </div>
        )}

        {step === 2 && (
          <form onSubmit={handleRegister} className="space-y-4">
            <h2 className="text-2xl font-bold mb-4">Create Account</h2>
            <input 
              placeholder="Full Name" 
              className="w-full p-3 border rounded-xl" 
              onChange={e => setForm({...form, fullname: e.target.value})}
              required
            />
            <input 
              type="email" 
              placeholder="Email Address" 
              className="w-full p-3 border rounded-xl" 
              onChange={e => setForm({...form, email: e.target.value})}
              required
            />
            <input 
              type="password" 
              placeholder="Password (min 8 chars)" 
              className="w-full p-3 border rounded-xl" 
              onChange={e => setForm({...form, password: e.target.value})}
              required
            />
            <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold">
              {loading ? "Registering..." : "Create Account"}
            </button>
          </form>
        )}

        {step === 3 && (
          <div className="text-center">
            <div className="text-5xl mb-4">✨</div>
            <h2 className="text-2xl font-bold mb-2">Success!</h2>
            <p className="text-slate-500 mb-6">Your account has been created.</p>
            <Link to="/login" className="block w-full bg-slate-900 text-white py-3 rounded-xl font-bold">Login Now</Link>
          </div>
        )}
      </div>
    </div>
  );
}
